#pragma scop
{
  const int T = 32;
  int ti, tj, i, j;

  for (t = 0; t < _PB_TMAX; t++) {
    #pragma omp parallel default(none) shared(t, _PB_NX, _PB_NY, ex, ey, hz, _fict_) private(ti, tj, i, j)
    {
      /* Fused ey row boundary, ey update, and ex update */
      #pragma omp for collapse(2) schedule(static)
      for (ti = 0; ti < _PB_NX; ti += T) {
        int imax = ti + T < _PB_NX ? ti + T : _PB_NX;
        for (tj = 0; tj < _PB_NY; tj += T) {
          int jmax = tj + T < _PB_NY ? tj + T : _PB_NY;
          for (i = ti; i < imax; ++i) {
            if (i == 0) {
              #pragma omp simd
              for (j = tj; j < jmax; ++j)
                ey[0][j] = _fict_[t];
            } else {
              #pragma omp simd
              for (j = tj; j < jmax; ++j)
                ey[i][j] = ey[i][j] - SCALAR_VAL(0.5) * (hz[i][j] - hz[i-1][j]);
            }
            int jstart = (tj == 0) ? 1 : tj;
            #pragma omp simd
            for (j = jstart; j < jmax; ++j)
              ex[i][j] = ex[i][j] - SCALAR_VAL(0.5) * (hz[i][j] - hz[i][j-1]);
          }
        }
      }

      /* hz update */
      #pragma omp for collapse(2) schedule(static)
      for (ti = 0; ti < _PB_NX - 1; ti += T) {
        int imax = ti + T < _PB_NX - 1 ? ti + T : _PB_NX - 1;
        for (tj = 0; tj < _PB_NY - 1; tj += T) {
          int jmax = tj + T < _PB_NY - 1 ? tj + T : _PB_NY - 1;
          for (i = ti; i < imax; ++i) {
            #pragma omp simd
            for (j = tj; j < jmax; ++j)
              hz[i][j] = hz[i][j] - SCALAR_VAL(0.7) * (ex[i][j+1] - ex[i][j] +
                                                   ey[i+1][j] - ey[i][j]);
          }
        }
      }
    } /* end parallel */
  }
}
